 10	
 11	/** The document the guest gets when the reservation is confirmed, at check-out, and on request. */
 12	public record ReservationReceipt(
 13	        String title,
 14	        long reservationId,
 15	        String guestName,
 16	        String guestCpf,
 17	        String companyCnpj,
 18	        String companyName,
 19	        String guestPassport,
 20	        String guestCountry,
 21	        int roomNumber,
 22	        RoomType roomType,
 23	        LocalDate checkIn,
 24	        LocalDate checkOut,
 25	        int nights,
 26	        BigDecimal subtotal,
 27	        BigDecimal discount,
 28	        BigDecimal total,
 29	        String text) {
 30	
 31	    public ReservationReceipt(Reservation reservation, Room room) {
 32	        this(
 33	                titleFor(reservation.guest()),
 34	                reservation.id(),
 35	                reservation.guest().name(),
 36	                reservation.guest().cpf(),
 37	                reservation.guest().companyCnpj(),
 38	                reservation.guest().companyName(),
 39	                reservation.guest().passport(),
 40	                reservation.guest().country(),
 41	                room.number(),
 42	                room.type(),
 43	                reservation.checkIn(),
 44	                reservation.checkOut(),
 45	                reservation.price().nights(),
 46	                reservation.price().subtotal(),
 47	                reservation.price().discount(),
 48	                reservation.price().total(),
 49	                generateText(reservation, room));
 50	    }
 51	
 52	    private static String titleFor(Guest guest) {
 53	        if (guest.isCompany()) {
 54	            return "Fatura de hospedagem";
 55	        } else if (guest.isForeign()) {
 56	            return "Booking receipt";
 57	        } else {
 58	            return "Comprovante de reserva";
 59	        }
 60	    }
 61	
 62	    private static String generateText(Reservation reservation, Room room) {
 63	        Guest guest = reservation.guest();
 64	        if (guest.isCompany()) {
 65	            return generateInvoice(reservation, room);
 66	        } else if (guest.isForeign()) {
 67	            return generateBookingReceipt(reservation, room);
 68	        } else {
 69	            return generateReceipt(reservation, room);
 70	        }
 71	    }
 72	
 73	    private static String generateReceipt(Reservation reservation, Room room) {
 74	        StringBuilder text = new StringBuilder();
 75	        text.append("Comprovante de reserva nº ").append(reservation.id()).append('\n');
 76	        text.append("Hóspede: ").append(reservation.guest().name())
 77	                .append(" (CPF ").append(reservation.guest().cpf()).append(")\n");
 78	        text.append("Quarto: ").append(room.number()).append(" (").append(room.type()).append(")\n");
 79	        text.append("Entrada: ").append(TextFormat.date(reservation.checkIn()))
 80	                .append(" | Saída: ").append(TextFormat.date(reservation.checkOut()))
 81	                .append(" | ").append(reservation.price().nights())
 82	                .append(reservation.price().nights() == 1 ? " diária" : " diárias").append('\n');
 83	        text.append("Diárias: ").append(TextFormat.money(reservation.price().subtotal())).append('\n');
 84	        if (reservation.price().discount().signum() > 0) {
 85	            text.append("Desconto: ").append(TextFormat.money(reservation.price().discount())).append('\n');
 86	        }
 87	        text.append("Total: ").append(TextFormat.money(reservation.price().total())).append('\n');
 88	        return text.toString();
 89	    }
 90	
 91	    private static String generateInvoice(Reservation reservation, Room room) {
 92	        BigDecimal issWithheld = reservation.price().total()
 93	                .multiply(new BigDecimal("0.05"))
 94	                .setScale(2, java.math.RoundingMode.HALF_EVEN);
 95	        StringBuilder text = new StringBuilder();
 96	        text.append("Fatura de hospedagem nº ").append(reservation.id()).append('\n');
 97	        text.append("Empresa: ").append(reservation.guest().companyName())
 98	                .append(" (CNPJ ").append(reservation.guest().companyCnpj()).append(")\n");
 99	        text.append("Hóspede: ").append(reservation.guest().name()).append('\n');
100	        text.append("Quarto: ").append(room.number()).append(" (").append(room.type()).append(")\n");
101	        text.append("Entrada: ").append(TextFormat.date(reservation.checkIn()))
102	                .append(" | Saída: ").append(TextFormat.date(reservation.checkOut()))
103	                .append(" | ").append(reservation.price().nights())
104	                .append(reservation.price().nights() == 1 ? " diária" : " diárias").append('\n');
105	        text.append("Diárias: ").append(TextFormat.money(reservation.price().subtotal())).append('\n');
106	        if (reservation.price().discount().signum() > 0) {
107	            text.append("Desconto: ").append(TextFormat.money(reservation.price().discount())).append('\n');
108	        }
109	        text.append("Total: ").append(TextFormat.money(reservation.price().total())).append('\n');
110	        text.append("ISS retido (5%): ").append(TextFormat.money(issWithheld)).append('\n');
111	        return text.toString();
112	    }
113	
114	    private static String generateBookingReceipt(Reservation reservation, Room room) {
115	        StringBuilder text = new StringBuilder();
116	        text.append("Booking receipt no. ").append(reservation.id()).append('\n');
117	        text.append("Guest: ").append(reservation.guest().name())
118	                .append(" (passport ").append(reservation.guest().passport())
119	                .append(", ").append(reservation.guest().country()).append(")\n");
120	        text.append("Room: ").append(room.number()).append(" (").append(room.type()).append(")\n");
121	        text.append("Check-in: ").append(TextFormat.isoDate(reservation.checkIn()))
122	                .append(" | Check-out: ").append(TextFormat.isoDate(reservation.checkOut()))
123	                .append(" | ").append(reservation.price().nights())
124	                .append(reservation.price().nights() == 1 ? " night" : " nights").append('\n');
125	        text.append("Nights: ").append(TextFormat.brlMoney(reservation.price().subtotal())).append('\n');
126	        if (reservation.price().discount().signum() > 0) {
127	            text.append("Discount: ").append(TextFormat.brlMoney(reservation.price().discount())).append('\n');
128	        }
129	        text.append("Total: ").append(TextFormat.brlMoney(reservation.price().total())).append('\n');
130	        return text.toString();
131	    }
132	}
133	package hotel.web;
134	
135	import com.fasterxml.jackson.databind.ObjectMapper;
136	import com.fasterxml.jackson.databind.SerializationFeature;
137	import com.fasterxml.jackson.databind.json.JsonMapper;
138	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
139	import hotel.messages.SentMessages;
140	import hotel.reports.OccupancyReport;
141	import hotel.reports.RevenueReport;
142	import hotel.reservations.ErrorCode;
143	import hotel.reservations.Guest;
144	import hotel.reservations.HotelException;
145	import hotel.reservations.NewReservation;
146	import hotel.reservations.ReservationService;
147	import hotel.rooms.Rooms;
148	import io.javalin.Javalin;
149	import io.javalin.http.Context;
150	import io.javalin.json.JavalinJackson;
151	import java.time.LocalDate;
152	import java.time.YearMonth;
153	import java.time.format.DateTimeParseException;
154	
155	/** The HTTP API the inn's website and front desk call. */
156	public final class HttpApi {
157	
158	    private final Javalin server;
159	    private final Rooms rooms;
160	    private final ReservationService reservations;
161	    private final SentMessages sentMessages;
162	    private final OccupancyReport occupancyReport;
163	    private final RevenueReport revenueReport;
164	
165	    public HttpApi(
166	            Rooms rooms,
167	            ReservationService reservations,
168	            SentMessages sentMessages,
169	            OccupancyReport occupancyReport,
170	            RevenueReport revenueReport) {
171	        this.rooms = rooms;
172	        this.reservations = reservations;
173	        this.sentMessages = sentMessages;
174	        this.occupancyReport = occupancyReport;
175	        this.revenueReport = revenueReport;
176	
177	        ObjectMapper jsonMapper = JsonMapper.builder()
178	                .addModule(new JavaTimeModule())
179	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
180	                .build();
181	        this.server = Javalin.create(config -> {
182	            config.showJavalinBanner = false;
183	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
184	        });
185	        registerRoutes();
186	        registerErrorHandling();
187	    }
188	
189	    public Javalin server() {
190	        return server;
191	    }
192	
193	    private void registerRoutes() {
194	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
195	
196	        server.post("/reservations", ctx -> {
197	            NewReservation request = readNewReservation(ctx);
198	            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
199	        });
200	        server.get("/reservations/{id}", ctx ->
201	                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
202	        server.post("/reservations/{id}/confirmation", ctx ->
203	                ctx.json(new ReservationResponse(reservations.confirm(reservationId(ctx)))));
204	        server.post("/reservations/{id}/cancellation", ctx ->
205	                ctx.json(new ReservationResponse(reservations.cancel(reservationId(ctx)))));
206	        server.post("/reservations/{id}/check-in", ctx ->
207	                ctx.json(new ReservationResponse(reservations.checkIn(reservationId(ctx)))));
208	        server.post("/reservations/{id}/check-out", ctx ->
209	                ctx.json(reservations.checkOut(reservationId(ctx))));
210	        server.get("/reservations/{id}/document", ctx ->
211	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
212	
213	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
214	
215	        server.get("/reports/occupancy", ctx -> {
216	            LocalDate night = readDate(ctx);
217	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
218	        });
219	        server.get("/reports/revenue", ctx -> {
220	            YearMonth month = readMonth(ctx);
221	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
222	        });
223	    }
224	
225	    private void registerErrorHandling() {
226	        server.exception(HotelException.class, (exception, ctx) -> {
227	            ctx.status(httpStatus(exception.errorCode()));
228	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
229	        });
230	    }
231	
232	    private static int httpStatus(ErrorCode errorCode) {
233	        return switch (errorCode) {
234	            case INVALID_REQUEST -> 400;
235	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
236	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
237	            case CAPACITY_EXCEEDED -> 422;
238	        };
239	    }
240	
241	    private static NewReservation readNewReservation(Context ctx) {
242	        CreateReservationRequest body;
243	        try {
244	            body = ctx.bodyAsClass(CreateReservationRequest.class);
245	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
246	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
247	        }
248	        if (body == null
249	                || body.roomNumber() == null
250	                || isBlank(body.guestName())
251	                || isBlank(body.guestEmail())
252	                || body.checkIn() == null
253	                || body.checkOut() == null
254	                || body.guests() == null
255	                || body.ratePlan() == null) {
256	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
257	        }
258	
259	        boolean hasIndividual = !isBlank(body.guestCpf());
260	        boolean hasCompany = !isBlank(body.companyCnpj()) && !isBlank(body.companyName());
261	        boolean hasForeign = !isBlank(body.guestPassport()) && !isBlank(body.guestCountry());
262	
263	        int identificationCount = (hasIndividual ? 1 : 0) + (hasCompany ? 1 : 0) + (hasForeign ? 1 : 0);
264	        if (identificationCount != 1) {
265	            throw new HotelException(
266	                    ErrorCode.INVALID_REQUEST,
267	                    "exactly one identification type is required: guestCpf, or companyCnpj with companyName, "
268	                            + "or guestPassport with guestCountry");
269	        }
270	
271	        Guest guest = new Guest(
272	                body.guestName(),
273	                body.guestEmail(),
274	                body.guestCpf(),
275	                body.companyCnpj(),
276	                body.companyName(),
277	                body.guestPassport(),
278	                body.guestCountry());
279	        return new NewReservation(
280	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
281	    }
282	
283	    private static long reservationId(Context ctx) {
284	        String id = ctx.pathParam("id");
285	        try {
286	            return Long.parseLong(id);
287	        } catch (NumberFormatException notANumber) {
288	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
289	        }
290	    }
291	
292	    private static LocalDate readDate(Context ctx) {
293	        String date = requiredQueryParam(ctx, "date");
294	        try {
295	            return LocalDate.parse(date);
296	        } catch (DateTimeParseException badDate) {
297	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
298	        }
299	    }
300	
301	    private static YearMonth readMonth(Context ctx) {
302	        String month = requiredQueryParam(ctx, "month");
303	        try {
304	            return YearMonth.parse(month);
305	        } catch (DateTimeParseException badMonth) {
306	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
307	        }
308	    }
309	
310	    private static String requiredQueryParam(Context ctx, String name) {
311	        String value = ctx.queryParam(name);
312	        if (value == null) {
313	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
314	        }
315	        return value;
316	    }
317	
318	    private static boolean isBlank(String text) {
319	        return text == null || text.isBlank();
320	    }
321	}
322	package hotel.reservations;
323	
324	public record Guest(
325	        String name,
326	        String email,
327	        String cpf,
328	        String companyCnpj,
329	        String companyName,
330	        String passport,
331	        String country) {
332	
333	    public Guest(String name, String email, String cpf) {
334	        this(name, email, cpf, null, null, null, null);
335	    }
336	
337	    public boolean isIndividual() {
338	        return cpf != null;
339	    }
340	
341	    public boolean isCompany() {
342	        return companyCnpj != null;
343	    }
344	
345	    public boolean isForeign() {
346	        return passport != null;
347	    }
348	}

