194	import java.math.BigDecimal;
195	import java.time.LocalDate;
196	import java.time.format.DateTimeFormatter;
197	import java.util.Locale;
198	
199	/** How money and dates are written in the texts the guest reads. */
200	public final class TextFormat {
201	
202	    private static final Locale BRAZIL = Locale.forLanguageTag("pt-BR");
203	    private static final Locale US = Locale.US;
204	    private static final DateTimeFormatter BRAZILIAN_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
205	    private static final DateTimeFormatter ISO_DATE = DateTimeFormatter.ISO_LOCAL_DATE;
206	
207	    private TextFormat() {
208	    }
209	
210	    public static String money(BigDecimal amount) {
211	        return "R$ " + String.format(BRAZIL, "%,.2f", amount);
212	    }
213	
214	    public static String date(LocalDate date) {
215	        return BRAZILIAN_DATE.format(date);
216	    }
217	
218	    public static String brlMoney(BigDecimal amount) {
219	        return "BRL " + String.format(US, "%,.2f", amount);
220	    }
221	
222	    public static String isoDate(LocalDate date) {
223	        return ISO_DATE.format(date);
224	    }
225	}
