247	        ReservationStore store = new ReservationStore(dataSource);
248	        SentMessages sentMessages = new SentMessages(dataSource);
249	        ReservationService reservations =
250	                new ReservationService(rooms, store, new PriceCalculator(), new EmailSender(sentMessages));
251	        HttpApi api = new HttpApi(
